"""Publish compact, identity-checked eye close-ups into the existing review Site."""
import hashlib,json
from pathlib import Path
from PIL import Image
repo=Path(__file__).resolve().parent.parent;root=repo/'artifacts/fauna-painted-20261024';site=repo/'artifacts/fauna-phone-review/dist';dest=site/'eyes';dest.mkdir(exist_ok=True)
rows=json.loads((site/'overview/index.json').read_text())['modes']['side']['pages'];number={}
for row in rows:
 for offset,name in enumerate(row['names']):number[name]=row['first']+offset
jobs=json.loads((root/'paint-queue.json').read_text())['jobs'];index=[];ledger=[]
for j in jobs:
 slug=j['slug'];folder=root/slug;receipt=json.loads((folder/'eye-audit/revision.json').read_text());digest=hashlib.sha256((folder/'Animal - Painted Species Review.blend').read_bytes()).hexdigest()
 assert receipt['blend_sha256']==digest and not receipt['actual_after_vision_pending'],slug
 record={'slug':slug,'name':j['animal'],'number':number[j['animal']],'images':{}}
 for view in ['front','right','left']:
  record['images'][view]={}
  for stage in ['after','before']:
   source=folder/f'eye-audit/{view}-{stage}.png';filename=f'{slug}-{view}-{stage}.webp'
   with Image.open(source) as im:im.convert('RGB').save(dest/filename,quality=90,method=6)
   record['images'][view][stage]=filename
   ledger.append({'slug':slug,'file':filename,'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'blend_sha256':digest if stage=='after' else json.loads((folder/'eye-audit/capture.json').read_text()).get('source_sha256')})
 index.append(record)
(dest/'index.json').write_text(json.dumps({'animals':index,'count':len(index)},ensure_ascii=False,separators=(',',':'))+'\n')
(site.parent/'checks/eye-inputs.json').write_text(json.dumps(ledger,indent=2)+'\n')
(site/'eyes.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Eye close-ups · WorldGen</title><style>
*{box-sizing:border-box}body{margin:0;background:#f2f1e9;color:#182925;font-family:system-ui,sans-serif}main{max-width:760px;margin:auto;padding:22px 16px 45px}a{color:#285d47}nav,.line{display:flex;gap:10px;justify-content:space-between;align-items:center;flex-wrap:wrap}h1{font-size:36px;letter-spacing:-.04em;margin-bottom:8px}p{line-height:1.5;color:#526259}button,select,input{font:inherit;min-height:44px;padding:10px 12px;border:1px solid #acbaaf;border-radius:10px;background:white;color:#182925}button{cursor:pointer}button[aria-pressed=true]{background:#285d47;color:white}.tabs{display:flex;gap:8px;margin:16px 0;flex-wrap:wrap}.tabs button{flex:1}select,input{width:100%;margin-top:10px}.image{display:block;border-radius:12px;overflow:hidden;background:#626b70}.image img{display:block;width:100%;height:auto}.status{font-size:14px}#title{margin:20px 0 12px}#previous,#next{flex:1}.caption{font-size:13px}
</style></head><body><main><nav><strong>WorldGen · Eye review</strong><a href="overview.html">All animals →</a></nav><h1>Eye close-ups</h1><p>Revised socket placement, eye size and surrounding lids. Check each head from the front and both sides; tap the picture to zoom.</p><input id="search" type="search" placeholder="Find an animal" aria-label="Find an animal"><select id="animal" aria-label="Animal"></select><div class="line" style="margin-top:10px"><button id="previous">← Previous</button><button id="next">Next →</button></div><h2 id="title"></h2><div class="tabs" role="group" aria-label="Head view"><button data-view="front" aria-pressed="true">Front</button><button data-view="right" aria-pressed="false">Right</button><button data-view="left" aria-pressed="false">Left</button></div><div class="tabs" role="group" aria-label="Revision"><button data-stage="after" aria-pressed="true">Revised</button><button data-stage="before" aria-pressed="false">Before</button></div><a class="image" id="zoom"><img id="photo" width="512" height="512" alt=""></a><p id="status" class="status"></p><p class="caption">171 selected generated bodies. The accepted deer and five tiny ambient-fauna groups remain on the overview. These close-ups show appearance; motion still needs individual review.</p></main><script>
let all=[],list=[],selected='',view='front',stage='after';const $=s=>document.querySelector(s);function show(){const row=all.find(r=>r.slug===selected);if(!row)return;const path='eyes/'+row.images[view][stage];$('#photo').src=path;$('#photo').alt=row.name+' '+view+' '+stage;$('#zoom').href=path;$('#title').textContent=String(row.number).padStart(3,'0')+' · '+row.name;$('#status').textContent=(stage==='after'?'Revised':'Before this eye pass')+' · '+view+' view';$('#animal').value=selected;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view===view));document.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.stage===stage));history.replaceState(null,'','#'+selected)}function options(){const query=$('#search').value.toLowerCase();list=all.filter(r=>r.name.toLowerCase().includes(query));$('#animal').replaceChildren(...list.map(r=>{const o=document.createElement('option');o.value=r.slug;o.textContent=String(r.number).padStart(3,'0')+' '+r.name;return o}));if(list.length&&!list.some(r=>r.slug===selected))selected=list[0].slug;show()}fetch('eyes/index.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{all=d.animals;selected=all.some(r=>r.slug===location.hash.slice(1))?location.hash.slice(1):all[0].slug;options()}).catch(()=>$('#status').textContent='Could not load the eye review. Please refresh.');$('#search').addEventListener('input',options);$('#animal').addEventListener('change',e=>{selected=e.target.value;show()});for(const [id,step] of [['previous',-1],['next',1]])$('#'+id).addEventListener('click',()=>{if(!list.length)return;const i=list.findIndex(r=>r.slug===selected);selected=list[(i+step+list.length)%list.length].slug;show()});document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;show()}));document.querySelectorAll('[data-stage]').forEach(b=>b.addEventListener('click',()=>{stage=b.dataset.stage;show()}));
</script></body></html>''',encoding='utf-8')
overview=site/'overview.html';text=overview.read_text(encoding='utf-8')
if 'href="eyes.html"' not in text:text=text.replace('<h1>All 177 animals &amp; groups</h1>','<h1>All 177 animals &amp; groups</h1><p><a href="eyes.html">Open the revised eye close-ups →</a></p>')
overview.write_text(text,encoding='utf-8')
print('Eye gallery',len(index),'animals',len(ledger),'images')
